import { test, expect } from '@playwright/test';

test.describe('Virus Scan Status for Uploaded Files', () => {
  let uploadedFileName: string;

  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
    uploadedFileName = `test-file-${Date.now()}.txt`;
  });

  test('should display virus scan status as pending when file is uploaded', async ({ page }) => {
    // Create a test file
    const fileContent = 'This is a test file for virus scanning';
    const buffer = Buffer.from(fileContent);

    // Upload file
    const fileInput = page.getByLabel('File upload');
    await fileInput.setInputFiles({
      name: uploadedFileName,
      mimeType: 'text/plain',
      buffer: buffer,
    });

    // Verify file appears in the list
    const fileItem = page.getByText(uploadedFileName);
    await expect(fileItem).toBeVisible();

    // Check for pending scan status
    const scanStatus = page.getByText(/Scanning|Pending|In Progress/i);
    await expect(scanStatus).toBeVisible();

    // Verify scan status badge is displayed
    const statusBadge = page.getByRole('status');
    await expect(statusBadge).toContainText(/Scanning|Pending/i);
  });

  test('should display virus scan status as completed with result', async ({ page }) => {
    // Create and upload a test file
    const fileContent = 'Safe test file content';
    const buffer = Buffer.from(fileContent);

    const fileInput = page.getByLabel('File upload');
    await fileInput.setInputFiles({
      name: uploadedFileName,
      mimeType: 'text/plain',
      buffer: buffer,
    });

    // Wait for scan to complete
    const scanCompleteStatus = page.getByText(/Clean|Safe|No threats detected/i);
    await expect(scanCompleteStatus).toBeVisible({ timeout: 10000 });

    // Verify the file row shows completion status
    const fileRow = page.getByRole('row').filter({ has: page.getByText(uploadedFileName) });
    await expect(fileRow).toBeVisible();

    // Check for scan result details
    const scanResult = page.getByRole('cell').filter({ hasText: /Clean|Safe|No threats/i });
    await expect(scanResult).toBeVisible();
  });

  test('should display virus scan status with timestamp', async ({ page }) => {
    // Upload a file
    const fileContent = 'Test file with timestamp';
    const buffer = Buffer.from(fileContent);

    const fileInput = page.getByLabel('File upload');
    await fileInput.setInputFiles({
      name: uploadedFileName,
      mimeType: 'text/plain',
      buffer: buffer,
    });

    // Wait for scan to complete
    await page.waitForTimeout(2000);

    // Verify scan status is visible
    const scanStatus = page.getByText(/Scanned|Completed|Finished/i);
    await expect(scanStatus).toBeVisible({ timeout: 10000 });

    // Check for timestamp in scan status
    const timestamp = page.getByText(/\d{1,2}:\d{2}|AM|PM/);
    await expect(timestamp).toBeVisible();
  });

  test('should show different status for infected file', async ({ page }) => {
    // Upload a file that triggers threat detection
    const fileContent = 'X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*';
    const buffer = Buffer.from(fileContent);

    const fileInput = page.getByLabel('File upload');
    await fileInput.setInputFiles({
      name: uploadedFileName,
      mimeType: 'text/plain',
      buffer: buffer,
    });

    // Wait for scan to complete
    await page.waitForTimeout(2000);

    // Verify threat detected status
    const threatStatus = page.getByText(/Threat detected|Infected|Quarantined/i);
    await expect(threatStatus).toBeVisible({ timeout: 10000 });

    // Verify warning icon or alert is displayed
    const warningIcon = page.getByRole('img', { name: /warning|alert|threat/i });
    await expect(warningIcon).toBeVisible();

    // Verify file is marked as unsafe
    const unsafeIndicator = page.getByText(/Unsafe|Dangerous|Blocked/i);
    await expect(unsafeIndicator).toBeVisible();
  });

  test('should allow user to view detailed scan report', async ({ page }) => {
    // Upload a file
    const fileContent = 'File for detailed scan report';
    const buffer = Buffer.from(fileContent);

    const fileInput = page.getByLabel('File upload');
    await fileInput.setInputFiles({
      name: uploadedFileName,
      mimeType: 'text/plain',
      buffer: buffer,
    });

    // Wait for scan to complete
    await page.waitForTimeout(2000);

    // Click on view details button
    const detailsButton = page.getByRole('button', { name: /View Details|View Report|Details/i });
    await expect(detailsButton).toBeVisible({ timeout: 10000 });
    await detailsButton.click();

    // Verify detailed report is displayed
    const reportTitle = page.getByRole('heading', { name: /Scan Report|Details/i });
    await expect(reportTitle).toBeVisible();

    // Verify report contains scan information
    const scanInfo = page.getByText(/Engine|Signature|Definition/i);
    await expect(scanInfo).toBeVisible();

    // Verify close button is available
    const closeButton = page.getByRole('button', { name: /Close|Done|Back/i });
    await expect(closeButton).toBeVisible();
  });
});
